import json, glob, re, collections, os, sys
H = os.path.dirname(os.path.abspath(__file__))
recs = []
for f in sorted(glob.glob(H + '/raw/*.json')):
    for r in json.load(open(f)):
        recs.append(r)
assign = json.load(open(H + '/tax/assign.json'))
name2page = collections.defaultdict(list)
for k, v in assign.items():
    for n in v:
        name2page[n.lower()].append(k)
order = [p['slug'] for s in json.load(open(H + '/taxonomy.json'))['sections'] if s['id'] == 'motion' for p in s['pages']]


def fmt(r):
    s = '%s [%s] %s :: %s' % (r['id'], r['area'], r['name'], r['what'])
    if r.get('ui'):
        s += ' UI=' + ' / '.join(r['ui'])
    if r.get('mcp'):
        s += ' MCP=' + ','.join(r['mcp'])
    if r.get('requires'):
        s += ' REQ=' + ','.join(r['requires'])
    if r.get('details'):
        s += ' DET=' + ' | '.join(r['details'])
    s += ' EV=' + str(r.get('evidence', ''))
    return s


groups = collections.defaultdict(list)
for r in recs:
    ps = name2page.get(r['name'].lower(), [])
    mp = [p for p in ps if p.startswith('motion/')]
    if mp:
        groups[mp[0]].append(r)
    elif r['area'] in ('motion', 'transitions'):
        groups['OTHER:' + (ps[0] if ps else 'none')].append(r)
out = open(H + '/motion_dump.txt', 'w')
keys = order + sorted(k for k in groups if k not in order)
for k in keys:
    out.write('\n=== %s (%d)\n' % (k, len(groups[k])))
    for r in sorted(groups[k], key=lambda r: r['id']):
        out.write(fmt(r) + '\n')
out.close()
seen = {r['id'] for g in groups.values() for r in g}
kw = re.compile(r'\b(actions?|keyframes?|keyed|preset|presets|transitions?|dissolve|motion|motion blur|region|wipe|push|ease|easing|in/out|during|slide up|end state)\b', re.I)
oth = [r for r in recs if r['id'] not in seen and kw.search(' '.join([r['name'], r['what'], ' '.join(r.get('ui') or []), ' '.join(r.get('details') or [])]))]
print(len(oth), collections.Counter(r['area'] for r in oth))
o = open(H + '/motion_dump_others.txt', 'w')
for r in sorted(oth, key=lambda r: (r['area'], r['id'])):
    o.write(fmt(r) + '\n')
o.close()
print(os.path.getsize(H + '/motion_dump.txt'), os.path.getsize(H + '/motion_dump_others.txt'))

